target.css:
:root {
  --ink: #29352b;
  --paper: #fffdf5;
  --line: #d8d0ba;
  --leaf: #557348;
  --cream: #f3ead2;
  --berry: #a84b42;
}

.blend-card {
  box-sizing: border-box;
  width: 470px;
  padding: 14px 16px;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.blend-card header,
.blend-card footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.stamp {
  padding: 4px 8px;
  border-radius: 5px;
  background: var(--leaf);
  color: var(--paper);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

.weight {
  color: var(--leaf);
  font-size: 13px;
  font-weight: 700;
}

.blend-card h1 {
  margin: 10px 0;
  font-size: 23px;
  line-height: 1;
}

.details {
  display: flex;
  gap: 8px;
  padding: 9px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.details span {
  flex: 1;
  color: var(--leaf);
  font-size: 12px;
  line-height: 1.25;
}

.blend-card footer {
  padding-top: 10px;
  color: var(--berry);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.4px;
}

.blend-card button {
  padding: 5px 9px;
  border: 1px solid var(--berry);
  border-radius: 999px;
  background: var(--cream);
  color: var(--berry);
  font-size: 11px;
  font-weight: 700;
}

